    "@sveltejs/vite-plugin-svelte": "^5.1.1",
    "@types/node": "^20.11.0",
    "@types/vscode": "^1.85.0",
    "@vitest/coverage-v8": "^3.2.4",
    "@vscode/vsce": "^3.0.0",
    "concurrently": "^9.0.0",
    "esbuild": "^0.25.12",
    "happy-dom": "^20.9.0",
    "svelte": "^5.55.7",
    "typescript": "^5.5.0",
    "vitest": "^3.2.4"
  },
  "dependencies": {
    "@vscode/codicons": "^0.0.45"
  }
}
